const jobs = new Map(); // job_id -> 'running' | 'cancelled'

const jobIdSchema = {
  type: 'object',
  properties: {
    job_id: { type: 'string' },
  },
  required: ['job_id'],
  additionalProperties: false,
};

export async function listTools() {
  return [
    {
      name: 'start_job',
      description: 'Start a job. Requires job_id and returns a running status. Rejects duplicate active jobs.',
      inputSchema: jobIdSchema,
    },
    {
      name: 'cancel_job',
      description: 'Cancel an active job. Requires job_id, changes an active job to cancelled, and rejects missing jobs or repeated cancellation.',
      inputSchema: jobIdSchema,
    },
  ];
}

function assertJobId(args) {
  if (
    args === null ||
    typeof args !== 'object' ||
    typeof args.job_id !== 'string' ||
    args.job_id.length === 0
  ) {
    const err = new Error('job_id is required and must be a non-empty string');
    err.code = -32602;
    throw err;
  }
  return args.job_id;
}

function textResult(text) {
  return { content: [{ type: 'text', text }] };
}

export async function callTool(name, args = {}) {
  if (name === 'start_job') {
    const jobId = assertJobId(args);
    const status = jobs.get(jobId);
    if (status === 'running') {
      const err = new Error(`job ${jobId} is already running`);
      err.code = -32603;
      throw err;
    }
    jobs.set(jobId, 'running');
    return textResult(`job ${jobId} is running`);
  }

  if (name === 'cancel_job') {
    const jobId = assertJobId(args);
    const status = jobs.get(jobId);
    if (status === undefined) {
      const err = new Error(`job ${jobId} not found`);
      err.code = -32602;
      throw err;
    }
    if (status === 'cancelled') {
      const err = new Error(`job ${jobId} is already cancelled`);
      err.code = -32603;
      throw err;
    }
    jobs.set(jobId, 'cancelled');
    return textResult(`job ${jobId} is cancelled`);
  }

  const err = new Error(`unknown tool: ${name}`);
  err.code = -32601;
  throw err;
}
